insert into "Hackathon" ("id","slug","title","tagline","description","status","startDate","endDate","submissionDeadline","prizePool","tracks","rules","faqs","sponsors","createdAt","updatedAt")
values ('gh-bolo-and-build','bolo-and-build','Bolo & Build','Build something for India. Say every line out loud.','A one-day, voice-only build, 10am to 6pm IST. Pick a problem for India, build the app with any coding agent, and drive it entirely by voice with Wispr Flow. Then publish your build log on RepoRally so the next builder can learn from it.','UPCOMING','2026-12-13T04:30:00.000Z'::timestamp,'2026-12-13T12:30:00.000Z'::timestamp,'2026-12-13T12:30:00.000Z'::timestamp,'Awards, certificates and recognition',$j$[{"id":"health","title":"Health: say it, understand it","prize":"Track Winner","description":"Help a patient or caregiver understand a prescription, describe symptoms or find the nearest care, in their own language, without typing.","tags":["healthcare","accessibility","multilingual"]},{"id":"farm","title":"Farmers: advice at the speed of speech","prize":"Track Winner","description":"Mandi prices, weather alerts and crop guidance for people who can't type on a small screen with muddy hands.","tags":["agritech","weather","markets"]},{"id":"learn","title":"Learning: a tutor in every classroom","prize":"Track Winner","description":"Tools for Tier 2 and Tier 3 students and government-school teachers: homework help, lesson planning, revision.","tags":["edtech","teachers","students"]},{"id":"shops","title":"Small business: run a kirana by talking","prize":"Track Winner","description":"Billing, stock and GST for the shopkeeper who has ten customers waiting and no time to type.","tags":["msme","billing","inventory"]},{"id":"citizen","title":"Citizens: schemes, forms, complaints","prize":"Track Winner","description":"Help people find the government schemes they qualify for, fill the forms, and file the complaints that get answered.","tags":["govtech","civic","forms"]}]$j$::jsonb,$j$["Teams of 1 to 4. Mixed skills are welcome: developers, designers, data people and first-time builders.","Pick one of the five tracks and build an app for that problem.","Use Wispr Flow to dictate your prompts and instructions to your coding agent. Typing is allowed for small fixes, but the build should be driven by voice.","Any coding agent and any model is fine: Claude Code, Codex, Cursor, GitHub Copilot, Open Code, Antigravity and others.","Start from a blank repository. Templates and boilerplate are fine, previously built projects are not.","Your repository must be public, with commits made during the event window.","Publish your build log on RepoRally. It is required for prize eligibility.","Submit by 15:30 IST: repo link, a demo video of 3 minutes or less, and the link to your build log.","Add a screenshot of your Wispr Flow stats to your build log as proof of voice use.","Judges' decisions are final. Be kind, credit your sources and respect other teams."]$j$::jsonb,$j$[{"q":"Do I have to use Wispr Flow?","a":"Yes. The whole point is building by voice with Wispr Flow. Typing is fine for small fixes, but the build should be driven by dictation."},{"q":"Does my app have to use voice?","a":"No. Your app can be anything useful for your track. The voice requirement is about how you build it."},{"q":"Can I join online?","a":"Yes. Online teams register the same way, build the same hours and submit the same things. Shortlisted online teams present on video in the finalist demos."},{"q":"What is the build log?","a":"A public article on RepoRally describing how you built your project by voice: the problem, example dictations, what worked, what broke and what you learned."},{"q":"Who are the judges?","a":"A panel of judges from global companies, mostly joining remotely. Names and the exact judging format will be announced on this page."},{"q":"Is it free?","a":"Yes, registration is free. Offline seats in Hyderabad are limited, so register early."},{"q":"Is this an official Wispr Flow event?","a":"It is a community event hosted by RepoRally, built around Wispr Flow. We are reaching out to Wispr and will update this page when anything is confirmed."}]$j$::jsonb,$j$[{"name":"RepoRally","tier":"Title","logoText":"RepoRally","perk":"Host platform: registration, Builder Passports, build-log publishing and certificates."}]$j$::jsonb,now(),now())
on conflict ("slug") do update set "title"=excluded."title","tagline"=excluded."tagline","description"=excluded."description","status"=excluded."status","startDate"=excluded."startDate","endDate"=excluded."endDate","submissionDeadline"=excluded."submissionDeadline","prizePool"=excluded."prizePool","tracks"=excluded."tracks","rules"=excluded."rules","faqs"=excluded."faqs","sponsors"=excluded."sponsors","updatedAt"=now();
